namespace ghidra.graph.viewer.renderer;






using edu.uci.ics.jung.graph;
using edu.uci.ics.jung.visualization;
using edu.uci.ics.jung.visualization;
using ghidra.graph.viewer;
using ghidra.graph.viewer.edge;

public class ArticulatedEdgeRenderer<V, E> : VisualEdgeRenderer<V, E> where V : VisualVertex where E : VisualEdge<V> {

	/* @Override */
	public Shape getEdgeShape(RenderContext<V, E> rc, Graph<V, E> graph, E e, float x1, float y1,
			float x2, float y2, bool isLoop, Shape vertexShape) {

		if (isLoop) {
			return GraphViewerUtils.createEgdeLoopInGraphSpace(vertexShape, x1, y1);
		}

		GeneralPath path = new GeneralPath();
		path.moveTo(x1, y1);

		// TODO investigate using the transformer directly
		// Function<? super E, Shape> edgeShapeTransformer = rc.getEdgeShapeTransformer();

		List<Point2D> articulations = e.getArticulationPoints();
		foreach (Point2D point in articulations) {
			double x = point.getX();
			double y = point.getY();
			Point2D offsetPoint = new Point2D.Double(x, y);
			point = rc.getMultiLayerTransformer().transform(Layer.LAYOUT, offsetPoint);

			x = point.getX();
			y = point.getY();
			path.lineTo(x, y);
		}

		path.lineTo(x2, y2);
		path.moveTo(x2, y2);
		path.closePath();

		return path;
	}
}
